var e={title:"💬 Vocabulário N3 — ciência e tecnologia",level:"H",subject:"japanese",objectives:["japanese.grammar"],difficulty:5,authorNotes:"Vocabulário N3 para ciência e tecnologia. Essencial para leitura de notícias e textos acadêmicos sobre inovação e pesquisa científica.",example:"Aprenda vocabulário científico N3. Ex.: 研究 → pesquisa.",passCriteria:{minAccuracyPercent:85,maxAvgSecondsPerExercise:22},pages:[{pageNumber:1,title:"Vocabulário científico — reconhecer",description:"Escolha o significado correto do vocabulário científico.",exercises:[{type:"japanese_vocab",question:"発明 (はつめい) (descoberta/invenção/pesquisa/teoria)",correctAnswer:"invenção",rationale:"発(lançar/produzir) + 明(tornar claro/iluminar) → 発明 = tornar claro algo novo = invenção. Diferença: 発見(descoberta) = achar o que já existia; 発明 = criar o que não existia.",difficulty:4,objectives:["japanese.grammar"]},{type:"japanese_vocab",question:"仮説 (かせつ) (teoria confirmada/hipótese/experimento/resultado)",correctAnswer:"hipótese",rationale:"仮(provisório/temporário) + 説(teoria/explicação) → 仮説 = teoria provisória a ser testada = hipótese. Etapa: 仮説 → 実験 → 証明 → 理論.",difficulty:4,objectives:["japanese.grammar"]},{type:"japanese_vocab",question:"観察 (かんさつ) (experimento/observação/análise/relatório)",correctAnswer:"observação",rationale:"観(olhar com atenção) + 察(perceber/intuir) → 観察 = olhar com atenção para perceber = observação sistemática.",difficulty:4,objectives:["japanese.grammar"]},{type:"japanese_vocab",question:"解析 (かいせき) (análise detalhada/observação/invenção/hipótese)",correctAnswer:"análise detalhada",rationale:"解(decompor/resolver) + 析(separar/dividir) → 解析 = decompor para entender = análise detalhada. Mais técnico que 分析(análise geral).",difficulty:4,objectives:["japanese.grammar"]},{type:"japanese_vocab",question:"人工知能 (じんこうちのう) (inteligência humana/robô/inteligência artificial/computador)",correctAnswer:"inteligência artificial",rationale:"人工(artificial: 人=humano + 工=fabricado) + 知能(inteligência: 知=saber + 能=capacidade) → 人工知能 = inteligência fabricada = IA.",difficulty:4,objectives:["japanese.grammar"]},{type:"japanese_vocab",question:"データベース (lista/banco de dados/diagrama/relatório)",correctAnswer:"banco de dados",rationale:"データ(data, do inglês) + ベース(base, do inglês) → データベース = base onde dados são armazenados e consultados = banco de dados.",difficulty:4,objectives:["japanese.grammar"]},{type:"japanese_vocab",question:"再生可能エネルギー (energia fóssil/energia renovável/energia nuclear/energia solar apenas)",correctAnswer:"energia renovável",rationale:"再生(regeneração: 再=de novo + 生=nascer) + 可能(possível) + エネルギー → energia que se regenera = renovável. Ex.: solar, eólica, hídrica.",difficulty:4,objectives:["japanese.grammar"]},{type:"japanese_vocab",question:"遺伝子 (いでんし) (célula/gene/átomo/proteína)",correctAnswer:"gene",rationale:"遺(transmitir/deixar como herança) + 伝(transmitir) + 子(partícula pequena) → 遺伝子 = partícula que transmite herança = gene.",difficulty:4,objectives:["japanese.grammar"]},{type:"japanese_vocab",question:"宇宙開発 (うちゅうかいはつ) (exploração submarina/desenvolvimento espacial/pesquisa climática/biologia marinha)",correctAnswer:"desenvolvimento espacial",rationale:"宇宙(espaço: 宇=universo + 宙=céu) + 開発(desenvolvimento: 開=abrir + 発=expandir) → 宇宙開発 = abrir e expandir o espaço = exploração/desenvolvimento espacial.",difficulty:4,objectives:["japanese.grammar"]},{type:"japanese_vocab",question:"ナノテクノロジー (biologia/nanotecnologia/astronomia/química)",correctAnswer:"nanotecnologia",rationale:"ナノ(nano, do grego = bilionésimo) + テクノロジー(tecnologia) → ナノテクノロジー = tecnologia em escala de nanômetros (10⁻⁹ m).",difficulty:4,objectives:["japanese.grammar"]}]},{pageNumber:2,title:"Vocabulário científico — uso em frases",description:"Escolha a palavra correta para completar as frases científicas.",exercises:[{type:"japanese_vocab",question:"この___が実証された (仮説/観察/解析/データベース)",correctAnswer:"仮説",rationale:"仮(provisório) + 説(teoria) → 仮説 = hipótese. 実証された = foi comprovado. Sequência: 仮説 → 実験 → 実証 = hipótese confirmada.",difficulty:5,objectives:["japanese.grammar"]},{type:"japanese_vocab",question:"エジソンは電球を___した (発明/観察/解析/仮説)",correctAnswer:"発明",rationale:"発(produzir) + 明(iluminar) → 発明する = inventar. エジソンは電球を発明した = Edison inventou a lâmpada (criou algo que não existia).",difficulty:5,objectives:["japanese.grammar"]},{type:"japanese_vocab",question:"大量の___を___した (データ/を/解析/観察)",correctAnswer:"解析",rationale:"解(decompor) + 析(separar) → 解析する = analisar em detalhe. 大量のデータを解析 = decompor grande volume de dados para extrair padrões.",difficulty:5,objectives:["japanese.grammar"]},{type:"japanese_vocab",question:"___が病気の原因を明らかにした (遺伝子研究/宇宙開発/データベース/ナノテクノロジー)",correctAnswer:"遺伝子研究",rationale:"遺伝子(gene: 遺=herança + 伝=transmitir + 子=partícula) + 研究 → 遺伝子研究 = pesquisa genética que revelou a causa da doença.",difficulty:5,objectives:["japanese.grammar"]},{type:"japanese_vocab",question:"___を活用した医療が進んでいる (人工知能/仮説/観察/解析)",correctAnswer:"人工知能",rationale:"人工(artificial) + 知能(inteligência) → 人工知能 = IA. 人工知能を活用した医療 = medicina que aproveita IA para diagnóstico e tratamento.",difficulty:5,objectives:["japanese.grammar"]},{type:"japanese_vocab",question:"___への転換が急がれる (再生可能エネルギー/宇宙開発/ナノテクノロジー/遺伝子)",correctAnswer:"再生可能エネルギー",rationale:"再生(regenerar) + 可能(possível) + エネルギー → energia renovável. 転換が急がれる = a transição é urgente (de combustíveis fósseis para renováveis).",difficulty:5,objectives:["japanese.grammar"]},{type:"japanese_vocab",question:"鳥の行動を___する (観察/発明/解析/仮説)",correctAnswer:"観察",rationale:"観(olhar atento) + 察(perceber) → 観察する = observar com atenção. 鳥の行動を観察する = método científico de observação sem interferência.",difficulty:5,objectives:["japanese.grammar"]},{type:"japanese_vocab",question:"大規模な___を構築した (データベース/仮説/観察/発明)",correctAnswer:"データベース",rationale:"データ(dados) + ベース(base) → データベース = sistema estruturado de armazenamento. 大規模なデータベースを構築した = construiu um grande repositório de dados.",difficulty:5,objectives:["japanese.grammar"]},{type:"japanese_vocab",question:"___を用いた薬の開発 (ナノテクノロジー/宇宙開発/観察/データベース)",correctAnswer:"ナノテクノロジー",rationale:"ナノ(10⁻⁹ m) + テクノロジー → nanotecnologia. ナノテクノロジーを用いた薬 = medicamento que entrega princípio ativo em escala nanométrica.",difficulty:5,objectives:["japanese.grammar"]},{type:"japanese_vocab",question:"___計画が承認された (宇宙開発/遺伝子/観察/仮説)",correctAnswer:"宇宙開発",rationale:"宇宙(espaço: 宇=universo + 宙=céu) + 開発(開=abrir + 発=expandir) → programa espacial. 宇宙開発計画が承認された = plano de exploração espacial aprovado.",difficulty:5,objectives:["japanese.grammar"]}]}],target:20},a=e.title,r=e.level,i=e.subject,o=e.objectives,t=e.difficulty,n=e.authorNotes,s=e.example,c=e.passCriteria,l=e.pages,p=e.target;export{n as authorNotes,e as default,t as difficulty,s as example,r as level,o as objectives,l as pages,c as passCriteria,i as subject,p as target,a as title};
